CREATE OR REPLACE FUNCTION public.collaboration_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb;b jsonb;wid uuid;pid uuid;tid uuid;eid uuid;label text;event text;uid uuid;target text;BEGIN
 r:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;b:=CASE WHEN TG_OP='INSERT' THEN '{}'::jsonb ELSE to_jsonb(OLD) END;wid:=(r->>'workspace_id')::uuid;pid:=(r->>'project_id')::uuid;eid:=(r->>'id')::uuid;label:=coalesce(r->>'title',r->>'name',r->>'file_name',r->>'email',r->>'content','Workspace member');event:=TG_TABLE_NAME||' '||lower(TG_OP);tid:=CASE WHEN TG_TABLE_NAME='tasks' THEN eid ELSE (r->>'task_id')::uuid END;
 IF TG_TABLE_NAME='attachments' AND (TG_OP<>'UPDATE' OR r->>'status'<>'Ready' OR b->>'status'='Ready') THEN RETURN COALESCE(NEW,OLD);END IF;
 INSERT INTO public.collaboration_activity(workspace_id,project_id,task_id,actor_id,action,entity_type,entity_id,title,metadata) VALUES(wid,pid,CASE WHEN TG_OP='DELETE' AND TG_TABLE_NAME='tasks' THEN NULL ELSE tid END,auth.uid(),event,TG_TABLE_NAME,eid,left(label,300),jsonb_build_object('before',CASE WHEN TG_OP='INSERT' THEN NULL ELSE b-'token_hash' END,'after',CASE WHEN TG_OP='DELETE' THEN NULL ELSE r-'token_hash' END));
 target:=CASE WHEN tid IS NOT NULL THEN '/projects/'||pid||'/tasks/'||tid ELSE '/projects/'||coalesce(pid,eid)||'/overview' END;
 IF TG_TABLE_NAME='tasks' AND TG_OP<>'DELETE' THEN
 IF nullif(r->>'assignee_id','') IS NOT NULL AND (TG_OP='INSERT' OR r->>'assignee_id' IS DISTINCT FROM b->>'assignee_id') THEN PERFORM public.enqueue_notification(wid,(r->>'assignee_id')::uuid,'assignment','Task assigned: '||(r->>'title'),'You have been assigned this task',target,'assignment:'||eid||':'||(r->>'version'));END IF;
 IF TG_OP='UPDATE' AND nullif(r->>'assignee_id','') IS NOT NULL AND (r->>'assignee_id')::uuid IS DISTINCT FROM auth.uid() AND (r->>'status' IS DISTINCT FROM b->>'status' OR r->>'due_date' IS DISTINCT FROM b->>'due_date') THEN PERFORM public.enqueue_notification(wid,(r->>'assignee_id')::uuid,'project','Task updated: '||(r->>'title'),'Status or due date changed',target,'task-update:'||eid||':'||(r->>'version'));END IF;
 ELSIF TG_TABLE_NAME='task_comments' AND TG_OP<>'DELETE' THEN
 FOR uid IN SELECT DISTINCT value::uuid FROM jsonb_array_elements_text(r->'mention_ids') LOOP IF uid<>(r->>'author_id')::uuid THEN PERFORM public.enqueue_notification(wid,uid,'mention','Mentioned in a task comment',left(r->>'content',300),target||'#discussion','mention:'||eid||':'||uid);END IF;END LOOP;
 IF TG_OP='INSERT' THEN FOR uid IN SELECT DISTINCT x FROM (SELECT assignee_id x FROM public.tasks WHERE id=tid UNION SELECT author_id FROM public.task_comments WHERE task_id=tid) q WHERE x IS NOT NULL AND x<>(r->>'author_id')::uuid AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(r->'mention_ids') v WHERE v.value=x::text) LOOP PERFORM public.enqueue_notification(wid,uid,'comment','New task comment',left(r->>'content',300),target||'#discussion','comment:'||eid||':'||uid);END LOOP;END IF;
 ELSIF TG_TABLE_NAME='projects' AND TG_OP='UPDATE' AND (r->>'status' IS DISTINCT FROM b->>'status' OR r->>'due_date' IS DISTINCT FROM b->>'due_date') THEN FOR uid IN SELECT DISTINCT x FROM (SELECT (r->>'owner_id')::uuid x UNION SELECT user_id FROM public.project_members WHERE project_id=eid) q WHERE x IS DISTINCT FROM auth.uid() LOOP PERFORM public.enqueue_notification(wid,uid,'project','Project updated: '||(r->>'name'),'Project status or deadline changed','/projects/'||eid||'/overview','project:'||eid||':'||(r->>'updated_at'));END LOOP;
 ELSIF TG_TABLE_NAME='milestones' AND TG_OP<>'DELETE' AND nullif(r->>'owner_id','') IS NOT NULL AND (r->>'owner_id')::uuid IS DISTINCT FROM auth.uid() AND (TG_OP='INSERT' OR r->>'status' IS DISTINCT FROM b->>'status') THEN PERFORM public.enqueue_notification(wid,(r->>'owner_id')::uuid,'milestone','Milestone: '||(r->>'title'),r->>'status','/projects/'||pid||'/milestones','milestone:'||eid||':'||(r->>'version'));
 ELSIF TG_TABLE_NAME='workspace_members' AND TG_OP='UPDATE' AND r->>'role' IS DISTINCT FROM b->>'role' THEN PERFORM public.enqueue_notification(wid,(r->>'user_id')::uuid,'invitation','Workspace role changed',r->>'role','/team','role:'||eid||':'||(r->>'updated_at'));
 END IF; RETURN COALESCE(NEW,OLD);END $$;